import{_ as o,C as a,o as n,c as s,a2 as r,E as i}from"./chunks/framework.CGSzHL4z.js";const g=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"reference/performance.md","filePath":"reference/performance.md","lastUpdated":1792705540000}'),l={name:"reference/performance.md"};function c(d,e,h,m,p,f){const t=a("Screenshot");return n(),s("div",null,[e[0]||(e[0]=r('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>How AcesMotion keeps Studio responsive and the runtime cheap in your game.</p><h2 id="in-your-game" tabindex="-1">In your game <a class="header-anchor" href="#in-your-game" aria-label="Permalink to &quot;In your game&quot;">​</a></h2><ul><li>The server sends one message per play, not one per frame. Clients evaluate scenes themselves from the server clock, so network traffic doesn&#39;t grow with scene length or frame rate.</li><li>Play time follows the server clock (<code>workspace:GetServerTimeNow()</code>), never the frame delta, so a hitch on one machine doesn&#39;t leave it behind. A client more than 0.05 s off re-anchors instead of drifting.</li><li>Joints are written once a frame in <code>PreSimulation</code>, after the Animator has posed the rig, so a scene blends over idle and walk without stopping it.</li><li>Scene data is stored in a compact binary form inside the place. <code>Preload</code> decodes scenes ahead of time so the first play doesn&#39;t hitch.</li><li><code>Configure { MaxDistance = ... }</code> lets clients skip scenes too far away to see.</li><li>At most 16 copies of one sound play at once; the oldest stops first.</li><li>Cast members are bound when they stream in, so StreamingEnabled games don&#39;t need every actor loaded.</li><li>The runtime has no outside dependencies: it is the engine plus two small packages (Signal and Trove).</li></ul><h2 id="in-studio" tabindex="-1">In Studio <a class="header-anchor" href="#in-studio" aria-label="Permalink to &quot;In Studio&quot;">​</a></h2><ul><li>The plugin and the runtime share the engine byte for byte, so there is one well-tested code path.</li><li>Time is stored as integer ticks, 6000 per second. Every common frame rate lands exactly on ticks, so changing the frame rate never shifts keys or accumulates rounding.</li><li>A scene is stored per chunk (one per actor). An edit rewrites only the chunks it touched, inside one undo step, so big scenes stay quick to edit and Team Create stays light.</li><li>The dope sheet is virtualised: only the rows and keys on screen exist, and their instances are reused as you scroll.</li><li>Audio waveforms are read in 2 second chunks as they scroll into view, and every zoom level is built from those chunks locally.</li><li>Motion trails sample at most 600 points, and the particle preview has a cap you control (Settings &gt; Effects).</li><li>The crash recovery copy is written 2 seconds after an edit instead of on every change, so it doesn&#39;t stall editing.</li></ul>',6)),i(t,{name:"performance-big-scene",caption:"A large scene scrolling smoothly in the dope sheet."})])}const y=o(l,[["render",c]]);export{g as __pageData,y as default};
